\begin{eqnarray}
\ln \left( (m+1)^{m-1} \right) & = & (m-1) \ln (m+1) \nonumber \\
& = & m \ln (m+1) + o(n) \nonumber \\
& = & m \ln n + m \ln \left( \frac{m+1}{n} \right) + o(n) \nonumber \\
& \geq & m \ln n + m \ln q + o(n) \nonumber \\
& \geq & m \ln n + n \ln q + o(n), \textrm{ since } q<1\label{eq:c1} 
\end{eqnarray}

Also, note that
\begin{eqnarray} 
k \ln k - x \ln n & = & (k-x) \ln n + k \ln k - k \ln n \nonumber \\
& = & (k-x) \ln n - n \frac{ \ln \left( \frac{n}{k} \right) }{\frac{n}{k}} \nonumber \\
& \geq & (k-x) \ln n - ne^{-1}, \phantom{www}
\textrm{ since } \frac{\ln y}{y} \leq e^{-1} \textrm{ } \forall y \nonumber \\
& = & \frac{cn}{\ln n} \ln n - ne^{-1} + o(n) \textrm{ by definition of } k \nonumber \\
& = & \left(c- e^{-1} \right) n + o(n). \label{eq:c2} 
\nonumber 
\end{eqnarray}

Thus, we have
\begin{eqnarray*}
& & \limsup_{n \to \infty} \frac{|\mathcal{P}(n)|}{k!(m+1)^{m-1}} \\
& \leq & \frac{(\gamma_{l})^{n} n!}{ \left( \frac{k}{e} \right)^{k} e^{m \ln n + n \ln q + o(n)}}, 
\textrm{$\phantom{w}$ by Proposition~\ref{gim T1}, Stirling's formula and (\ref{eq:c1})} \\
& = & \exp (n \ln \gamma_{l} + n \ln n -n +k - k \ln k - m \ln n - n \ln q + o(n)), \\
& & \textrm{using Stirling's formula for $n!$} \\
& = & \exp (n \ln \gamma_{l} -n +k - k \ln k + x \ln n - n \ln q + o(n)), \phantom{w} 
\textrm{ by definition of } x \\
& \leq & \exp (n \ln \gamma_{l} -n +k -\left(c-e^{-1}\right)n - n \ln q + o(n)), 
\phantom{www} \textrm{ by } (\ref{eq:c2}) \\
& \leq & \exp \left(n \left(\ln \left( \frac{\gamma_{l}}{q} \right) -c + e^{-1} + o(1) \right) \right),
\phantom{www} \textrm{ since } k \leq n +o(n) \\
& = & e^{- \Omega (n)} 
\textrm{, $\phantom{www}$ since $c> \ln \left( \frac{\gamma_{l}}{q} \right) + e^{-1}$}.
