e^{2} \left( \gamma_{D_{2},D_{2}} \right)^{h}}{D_{2}} \right)^{- \lceil \alpha k \rceil}, \\
& & \textrm{ since } e^{- \alpha k} \geq e^{- \lceil \alpha k \rceil} \\
& = & (1-\epsilon)^{k} ((1+\delta)k)! \left( \gamma_{D_{2},D_{2}} \right)^{(1+\delta)k}
(\alpha \beta)^{- \lceil \alpha k \rceil} \\
& \geq & (1-\epsilon)^{k} ((1+\delta)k)! \left( \gamma_{D_{2},D_{2}} \right)^{(1+\delta)k}
(\alpha \beta)^{- \alpha k} 
\textrm{, \phantom{www} since } \alpha \beta < 1 \\
& = & \left( \frac{1-\epsilon}{1-3\epsilon} \right)^{k} ((1+\delta)k)! \left( \gamma_{D_{2},D_{2}} \right)^{(1+\delta)k} 
\textrm{, \phantom{www} since } (\alpha \beta)^{\alpha} = 1-3 \epsilon \\
& \geq & \left( \frac{1-\epsilon}{1-3\epsilon} \right)^{k} 
\frac{|\mathcal{P}((1+\delta)k,D_{2},5,0,D_{2})|}{(1+\epsilon)^{(1+\delta)k}} 
\textrm{, \phantom{www} by (\ref{eq:gr2})} \\
& > & \left( \frac{1-\epsilon}{(1-3\epsilon)(1+\epsilon)^{2}} \right)^{k} 
|\mathcal{P}((1+\delta)k,D_{2},5,0,D_{2})| 
\textrm{, \phantom{w} since } \delta < 1 \textrm{ (page~\pageref{delta2}}) \\
& > & |\mathcal{P}((1+\delta)k,D_{2},5,0,D_{2})|,
\phantom{ww} \textrm{ since }(1-3\epsilon)(1+\epsilon)^{2} = 1 - \epsilon - 5 \epsilon^{2} - 3 \epsilon^{3}.
\end{eqnarray*}

